+void wvSplitKQ(const at::Tensor& in_b, const at::Tensor& in_a,
+               const std::optional<at::Tensor>& in_bias, at::Tensor& out_c,
+               const at::Tensor& scale_a, const at::Tensor& scale_b,
+               const int64_t CuCount) {
